def seg_cells(a,b):
    dr,dc=b[0]-a[0],b[1]-a[1]; n=max(abs(dr),abs(dc))
    if n==0: return []
    step_r = 0 if dr==0 else (1 if dr>0 else -1)
    step_c = 0 if dc==0 else (1 if dc>0 else -1)
    if dr!=0 and dc!=0 and abs(dr)!=abs(dc): return None
    return [(a[0]+step_r*i, a[1]+step_c*i) for i in range(1,n)]  # excluding endpoints

